PREFIX brick: <brick:/> PREFIX ref: <ref:/>
SELECT DISTINCT ?zone ?zone_uri ?t ?uri ?tsid ?uri2 ?tsid2 ?sp ?sp_name WHERE {
  ?zone brick:hasName "Perimeter_bot_ZN_1" .
  ?zone brick:hasSubgraph* ?point .
  ?point ref:hasTimeseriesId ?tsid .
  OPTIONAL { ?point ref:hasName ?sp_name }
} LIMIT 50

